class ContractPeriodKind(str, Enum):
    INITIAL_PRORATED = "INITIAL_PRORATED"
    FULL_RENEWAL = "FULL_RENEWAL"


class RenewalStatus(str, Enum):
    VIGENTE = "VIGENTE"
    PROXIMA_A_RENOVAR = "PROXIMA_A_RENOVAR"
    RENOVACION_PENDIENTE = "RENOVACION_PENDIENTE"
    PERIODO_DE_GRACIA = "PERIODO_DE_GRACIA"
    VENCIDA = "VENCIDA"
    BLOQUEADA = "BLOQUEADA"
    RENOVADA = "RENOVADA"


@dataclass(frozen=True)
class RenewalPolicy:
    cycle_start_month: int
    cycle_start_day: int
    grace_days: int
    upcoming_notice_days: int
    prorate_initial_period: bool = True


@dataclass(frozen=True)
class ContractPeriod:
    period_id: str
    contract_id: str
    kind: ContractPeriodKind
    valid_from: str
    valid_to: str
    annual_base_amount: float
    charged_amount: float
    renewal_status: RenewalStatus
    previous_period_id: Optional[str] = None


def validate_renewal_policy(policy: RenewalPolicy) -> None:
    if policy.cycle_start_month < 1 or policy.cycle_start_month > 12:
        raise ValueError("cycle_start_month debe estar entre 1 y 12")
    if policy.cycle_start_day < 1 or policy.cycle_start_day > 31:
        raise ValueError("cycle_start_day debe estar entre 1 y 31")
    if policy.grace_days < 0:
        raise ValueError("grace_days no puede ser negativo")
    if policy.upcoming_notice_days < 0:
        raise ValueError("upcoming_notice_days no puede ser negativo")


def validate_contract_period(period: ContractPeriod) -> None:
    for field_name, value in (("period_id", period.period_id), ("contract_id", period.contract_id), ("valid_from", period.valid_from), ("valid_to", period.valid_to)):
        if not str(value or "").strip():
            raise ValueError(f"ContractPeriod requiere {field_name}")
    if period.valid_to < period.valid_from:
        raise ValueError("valid_to no puede ser anterior a valid_from")
    if period.annual_base_amount < 0 or period.charged_amount < 0:
        raise ValueError("Los importes no pueden ser negativos")
    if period.kind == ContractPeriodKind.INITIAL_PRORATED:
        if period.charged_amount > period.annual_base_amount:
            raise ValueError("El periodo inicial prorrateado no puede exceder la tarifa anual base")
        return
    if period.kind == ContractPeriodKind.FULL_RENEWAL:
        if not str(period.previous_period_id or "").strip():
            raise ValueError("FULL_RENEWAL requiere previous_period_id para conservar trazabilidad historica")


def calculate_prorated_amount(annual_amount: float, active_days: int, cycle_days: int) -> float:
    if annual_amount < 0:
        raise ValueError("annual_amount no puede ser negativo")
    if cycle_days <= 0:
        raise ValueError("cycle_days debe ser mayor que cero")
    if active_days < 0 or active_days > cycle_days:
        raise ValueError("active_days debe estar entre 0 y cycle_days")
    return round(float(annual_amount) * (float(active_days) / float(cycle_days)), 2)


def derive_renewal_status(*, days_until_end: int, grace_days: int, upcoming_notice_days: int, renewed: bool = False, blocked: bool = False) -> RenewalStatus:
    if grace_days < 0 or upcoming_notice_days < 0:
        raise ValueError("Las ventanas de renovacion no pueden ser negativas")
    if renewed:
        return RenewalStatus.RENOVADA
    if blocked:
        return RenewalStatus.BLOQUEADA
    if days_until_end > upcoming_notice_days:
        return RenewalStatus.VIGENTE
    if days_until_end > 0:
        return RenewalStatus.PROXIMA_A_RENOVAR
    if days_until_end == 0:
        return RenewalStatus.RENOVACION_PENDIENTE
    if abs(days_until_end) <= grace_days:
        return RenewalStatus.PERIODO_DE_GRACIA
    return RenewalStatus.VENCIDA
